CREATE TRIGGER IF NOT EXISTS trg_iou_payments_ins AFTER INSERT ON iou_payments WHEN NEW.uid IS NULL OR NEW.updated_at IS NULL BEGIN UPDATE iou_payments SET uid = coalesce(NEW.uid, lower(hex(randomblob(16)))), updated_at = coalesce(NEW.updated_at, strftime('%Y-%m-%d %H:%M:%f', 'now')) WHERE rowid = NEW.rowid; END;

